interface.definition:
#"SYSTEM_SYSRULES_cardLayout"(
  showBorder: true,
  marginBelow: "STANDARD",
  contents: {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "Interview Detail",
      labelColor: "SECONDARY",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: "To be completed by DPP Operations",
              style: "EMPHASIS"
            )
        ),
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_dateTimeField"(
                  label: "Interview Date & Time",
                  value: ri!interview.interviewDateTime,
                  saveInto: {
                    ri!interview.interviewDateTime,
                    ri!interview.interviewDate
                  },
                  required: true
                ),
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Interview Location",
                  choiceLabels: { "Office", "Virtual" },
                  choiceValues: { "Office", "Virtual" },
                  choiceLayout: "COMPACT",
                  value: ri!interview.interviewLocation,
                  required: true,
                  saveInto: {
                    ri!interview.interviewLocation,
                    a!save(ri!interview.interviewOfficeLocation,null)
                  }
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895335"(
                  interview: ri!interview
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Office Location",
                  characterLimit: 100,
                  disabled: not(ri!interview.interviewLocation = "Office"),
                  required: ri!interview.interviewLocation = "Office",
                  value: ri!interview.interviewOfficeLocation,
                  saveInto: ri!interview.interviewOfficeLocation
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_paragraphField"(
          label: "DPP Operations Additional Comments for Interviewer",
          characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3426796",
          value: ri!interview.comments,
          saveInto: ri!interview.comments
        )
      }
    ),
    #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3858241"(
      interview: ri!interview,
      isInterviewerTask: false
    )
  },
  showWhen: ri!showWhen
)
